fn element_wise_subtract(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // We assume `arr1.len() == arr2.len()` and that each subtraction fits in i32.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a - b)
        .collect()
}

